actual_cli_stdout.background-processing:
{
  "id": "background-processing",
  "title": "background-processing",
  "overview": "Expose the persisted lifecycle of accepted background workflows, dependency-based task progression and bounded automatic retries, so callers can distinguish saved work from execution and completion.",
  "requirementCount": 32,
  "requirements": [
    {
      "name": "Validate workflow definitions before accepting work",
      "text": "A trigger SHALL load the named stored workflow definition and reject an unavailable definition, missing task dependency, dependency cycle or undeclared top-level string-payload placeholder before persisting a new instance. This rule SHALL NOT assign HTTP error codes to rejected definitions.",
      "scenarios": []
    },
    {
      "name": "Capture supplied parameters at acceptance",
      "text": "A trigger SHALL require the presence of every required parameter key and snapshot supplied parameters into the instance and task payloads. Missing optional parameters SHALL omit top-level string payload entries referencing them. Required-key presence SHALL NOT imply nonblank value validation.",
      "scenarios": []
    },
    {
      "name": "Persist initial workflow and task identities before returning",
      "text": "Successful orchestration acceptance SHALL return a new workflow-instance identity only after initial instance and task persistence commits. The instance SHALL be Pending; roots SHALL be Pending and dependency-bearing tasks Waiting, each with its own task identity and dependency names. Acceptance SHALL NOT certify execution or completion.",
      "scenarios": []
    },
    {
      "name": "Apply initial schedules to root tasks",
      "text": "A supplied initial schedule SHALL apply to every root Pending task and leave dependent Waiting tasks unscheduled. With no supplied schedule, roots SHALL remain unscheduled. A schedule SHALL establish earliest eligibility rather than an execution deadline.",
      "scenarios": []
    },
    {
      "name": "Select due pending tasks for processor dispatch",
      "text": "Worker selection SHALL consider Pending tasks whose schedule is absent or due, select at most ten per batch ordered by scheduled time, and dispatch selected work subject to its processor throttle. A task rescheduled into the future while awaiting its slot SHALL be skipped on reload. Selection SHALL NOT promise immediate execution or exclusive delivery.",
      "scenarios": []
    },
    {
      "name": "Record processor execution and successful task completion",
      "text": "Before dispatch, a task SHALL be saved as Processing with its prior error and stack trace cleared. Dispatch SHALL use the registered processor matching its processor name. A normally returning processor SHALL be recorded Completed when completion persistence succeeds; an absent matching processor SHALL enter failure handling. Completion SHALL NOT certify domain success beyond that processor return.",
      "scenarios": []
    },
    {
      "name": "Promote dependencies after successful task completion",
      "text": "On successful reconciliation after a task completes, Waiting tasks SHALL become Pending only when all their named dependencies are recorded Completed. Promotion SHALL NOT execute a dependent in the already selected batch solely because it was promoted.",
      "scenarios": []
    },
    {
      "name": "Derive completion from remaining task states",
      "text": "On successful completion reconciliation, an instance with no Waiting, Pending or Processing tasks SHALL become Completed if no task is Failed, or Failed if any task is Failed, unless the instance is Paused. Active tasks SHALL prevent this completion update. Paused status SHALL be retained by reconciliation.",
      "scenarios": []
    },
    {
      "name": "Classify automatic retry eligibility at the attempt boundary",
      "text": "Automatic retries SHALL require remaining retry allowance and either an explicit transient workflow exception, a recognized transient provider/network/timeout exception, or a recognized rate-limit message. Otherwise the attempt SHALL enter terminal failure handling. Classification SHALL concern the caught exception rather than an inferred diagnosis.",
      "scenarios": []
    },
    {
      "name": "Persist retries on the existing task",
      "text": "When automatic retry persistence succeeds, the task SHALL retain its identity, increment retryCount once, become Pending and store its next scheduled time and caught error message. Retry scheduling SHALL NOT itself promote dependencies, complete the task or certify recovery.",
      "scenarios": []
    },
    {
      "name": "Schedule automatic retries using configured delays and UTC windows",
      "text": "For positive incremented retry counts within the configured delay list, the next attempt SHALL be scheduled relative to failure-handling time using the corresponding delay. Later retries SHALL use a randomized minute in the next window whose configured UTC start is strictly later than scheduling time. Defaults SHALL be 1, 5, 20, 60 and 300 minutes, ten retries and a 01:00–05:00 UTC window.",
      "scenarios": []
    },
    {
      "name": "Stagger other pending work after recognized rate limiting",
      "text": "After a recognized rate-limit failure saves its own retry, successful proactive rescheduling SHALL move other Pending tasks with the same processor name to successive one-minute slots following that retry. Failure of this secondary save SHALL NOT undo the already saved primary retry.",
      "scenarios": []
    },
    {
      "name": "Retain terminal task failure and pause its workflow",
      "text": "When terminal task failure persistence succeeds, the task SHALL be Failed with a mapped error message and available exception stack trace. A subsequent successful parent update SHALL set the instance Paused. These saves SHALL NOT imply rollback of previously completed tasks or processor side effects, nor successful persistence of both states if a later save fails.",
      "scenarios": []
    },
    {
      "name": "Read stored lifecycle state by instance identity",
      "text": "A subsequent successful instance-detail read SHALL report stored instance and task status names with their identity, parameters, dependency names, retry counts, schedules, error messages and timestamps. An absent instance SHALL return 404. Reads SHALL preserve the distinction between instance state and task state rather than infer execution or success from acceptance.",
      "scenarios": []
    },
    {
      "name": "Apply shared household authentication to generic workflow operations",
      "text": "The five generic workflow operations SHALL require the shared household authentication policy. They SHALL NOT additionally require a selected family-member identity, recipe attribution or an administrative role.",
      "scenarios": []
    },
    {
      "name": "Bind generic workflow trigger parameters without an API schedule",
      "text": "POST /api/workflows/{workflowId}/trigger SHALL bind a JSON parameters dictionary of string values and pass it to orchestration with no initial schedule argument. Instance and task identity routes SHALL require GUID-shaped path values.",
      "scenarios": []
    },
    {
      "name": "List workflow instances by persisted active status",
      "text": "GET /api/workflows/active SHALL return 200 with a data array containing only instances whose stored status is Processing or Paused, ordered by descending updatedAt. Each summary SHALL expose id, workflowId, status, createdAt, updatedAt and taskCount.",
      "scenarios": []
    },
    {
      "name": "Read stored task diagnostics by task identity",
      "text": "GET /api/workflows/tasks/{taskId}/diagnostics SHALL return stored diagnostics for an existing task with its parent, without requiring Failed status. Successful responses SHALL use 200 data; an absent task SHALL return 404 with message \"Task not found.\".",
      "scenarios": []
    },
    {
      "name": "Reset an existing task without a failed-state guard",
      "text": "POST /api/workflows/tasks/{taskId}/reset SHALL apply reset to any existing task without testing its current status: set Pending, zero retryCount, schedule at current UTC time and clear errorMessage and stackTrace. After a successful save it SHALL return 200 data.message \"Task reset successfully.\"; an absent task SHALL return 404.",
      "scenarios": []
    },
    {
      "name": "Retain task context and selectively resume a reset parent",
      "text": "Reset SHALL retain task identity, payload, result, dependency names, createdAt and updatedAt, and SHALL NOT reset siblings. A found Paused parent SHALL become Processing in the reset save; other parent states and parent timestamps SHALL remain unchanged. Reset SHALL NOT cancel a running processor or validate dependencies.",
      "scenarios": []
    },
    {
      "name": "Attempt stale-task reclamation from the hosted loop",
      "text": "After initialization, the hosted worker SHALL attempt reclamation on its first loop and on later iterations when elapsed UTC time since its last completed reclamation call is strictly greater than five minutes. Reclamation SHALL precede pending-task selection in that iteration and SHALL NOT establish a reclamation deadline.",
      "scenarios": []
    },
    {
      "name": "Requeue processing tasks strictly older than the stale cutoff",
      "text": "Reclamation SHALL select Processing tasks with updatedAt strictly earlier than current UTC time minus fifteen minutes. On a successful reclamation save it SHALL set them Pending, increment retryCount, advance updatedAt and replace errorMessage with a reclamation message containing the prior updatedAt in universal sortable form.",
      "scenarios": []
    },
    {
      "name": "Retain reclamation context without applying retry or parent gates",
      "text": "Reclamation SHALL retain schedule, stackTrace, result, payload, dependencies, createdAt and task identity, and SHALL leave parent status and timestamps unchanged. It SHALL NOT check the automatic retry limit, parent state or processor liveness before requeuing a stale task.",
      "scenarios": []
    },
    {
      "name": "Contain reclamation failures at the loop boundary",
      "text": "Reclamation SHALL attempt one save for its selected task mutations, no save when no stale tasks are found, and catch and log query/save failures including cancellation exceptions. A returned failed attempt SHALL still advance the loop reclamation timestamp; it SHALL NOT certify persistence or successful restart.",
      "scenarios": []
    },
    {
      "name": "Poll pending work with capped idle backoff",
      "text": "After a batch attempt returns a positive selected-task count, the worker SHALL reset idle backoff and wait 500 milliseconds. Empty batches SHALL increase idle backoff from 1000 milliseconds, doubling to a 60000 millisecond cap. These delays SHALL NOT bound task start or completion time.",
      "scenarios": []
    },
    {
      "name": "Use local processor slots for dispatch",
      "text": "The hosted worker SHALL initialize processor slots from WorkflowThrottle: ExtractRecipe defaults to one slot with maximum one, GenerateHero to two with maximum two, and SyncRecipe to Default, default five. Unrecognized processor names SHALL receive five local slots. Slots SHALL be released after an entered execution attempt.",
      "scenarios": []
    },
    {
      "name": "Persist returned processor results without clearing prior results on null",
      "text": "When successful completion persistence succeeds, a non-null processor return SHALL replace the stored task result with camelCase JSON. A null return SHALL retain any existing result. This storage rule SHALL NOT add a result field to the approved task-detail wire contract.",
      "scenarios": []
    },
    {
      "name": "Start child workflows through shared acceptance",
      "text": "The StartWorkflow processor SHALL require a nonblank workflowId in its JSON payload, pass supplied parameters or an empty dictionary into shared acceptance, and return the child workflow ID, instance ID and resolved schedule. A missing or blank schedule cron SHALL produce no initial child schedule.",
      "scenarios": []
    },
    {
      "name": "Resolve child cron schedules against future UTC minutes",
      "text": "Child cron scheduling SHALL resolve a whole ${NAME} or ${NAME:-fallback} expression from nonblank configuration then nonblank fallback, and reject missing values. It SHALL parse five numeric cron fields and select the first matching whole UTC minute strictly after the supplied clock instant, searching no further than five years from its initial cursor.",
      "scenarios": []
    },
    {
      "name": "Prune only old terminal workflow history",
      "text": "When invoked, workflow-history pruning SHALL select Completed or Failed parents with updatedAt strictly earlier than its clock time minus retentionDays, remove those instances and their tasks on successful persistence, and return pruned instance/task counts. The processor SHALL default retentionDays to seven when absent or a numeric value cannot be read as a 32-bit integer.",
      "scenarios": []
    },
    {
      "name": "Retain terminal maintenance-command history for diagnosis",
      "text": "Dreaming SHALL prune only `completed` and `skipped` maintenance commands whose\n`completedAt` is at or before the injected UTC clock time minus the configured\nretention days. The processor SHALL default to 30 days and at most 500 deletions\nper invocation. `pending`, `processing` and `failed` commands SHALL be retained\nregardless of age. This policy SHALL be independent of workflow-history retention.",
      "scenarios": []
    },
    {
      "name": "Report maintenance-command pruning in Dreaming",
      "text": "Dreaming SHALL run maintenance-command pruning after command processing and before\nreport generation. The report SHALL include the committed deleted count and the\ncount of legacy completion timestamps initialized by that run. A pruning failure\nSHALL follow normal workflow dependency failure behavior and prevent a report from\nclaiming that the failed pruning work committed.",
      "scenarios": []
    }
  ],
  "metadata": {
    "version": "1.0.0",
    "format": "openspec"
  },
  "root": {
    "path": "/Users/alex/Code/whats-for-supper",
    "source": "nearest"
  }
}

actual_cli_stdout.deployment-calendar:
{
  "id": "deployment-calendar",
  "title": "deployment-calendar",
  "overview": "Provide authoritative deployment-local supper dates and Monday-based weeks, captured calendar references and expiry boundaries, independently of browser and server operating-system timezones.",
  "requirementCount": 7,
  "requirements": [
    {
      "name": "Resolve supper dates through the deployment calendar",
      "text": "Meal dates and Monday-based weeks SHALL use the configured deployment timezone at the supplied current instant, independently of server OS and browser timezone. An absent setting SHALL use UTC. An invalid explicit setting SHALL prevent startup with configuration guidance. Existing civil dates SHALL retain their literal values; operation timestamps SHALL remain UTC instants.",
      "scenarios": []
    },
    {
      "name": "Configure deployment timezone through shipped deployment templates",
      "text": "The shipped Synology environment template SHALL expose Calendar__TimeZone with default UTC and an IANA override example. Its Compose template SHALL pass that setting to the API, using UTC when omitted or empty. Supported repository API deployment templates SHALL carry the same setting. The PWA SHALL consume the API calendar without requiring a separate timezone setting.",
      "scenarios": []
    },
    {
      "name": "Document deployment timezone setup and changes",
      "text": "The Synology operator guide and household user guide SHALL explain administrator-owned deployment dates and the UTC default. Operator guidance SHALL name Calendar__TimeZone, show an IANA override, explain API recreation and invalid-value failure, and preserve existing environment values during upgrades. It SHALL distinguish meal dates from UTC timestamps and UTC maintenance schedules.",
      "scenarios": []
    },
    {
      "name": "Expose one authoritative calendar context with schedule reads",
      "text": "Successful schedule reads SHALL include the deployment timezone, captured UTC instant, current deployment date, current Monday, requested week's Monday and next deployment-day boundary as a UTC instant. All date context and returned dates SHALL derive from the same captured instant or explicit week reference. The requested week's identity SHALL remain distinct from the current week.",
      "scenarios": []
    },
    {
      "name": "Keep relative operations anchored to their intended calendar week",
      "text": "Relative schedule reads, suggestions, assignment, movement, defer, voting and locking SHALL accept an optional explicit Monday reference for their offsets. Omission SHALL use the deployment current Monday captured at operation entry. Browser actions SHALL retain their captured reference and target date through dependent requests and follow-ups. Invalid or non-Monday references SHALL return 400 before mutation.",
      "scenarios": []
    },
    {
      "name": "Refresh expired Today context before a new action",
      "text": "A newly initiated Today action SHALL use current authoritative deployment context. At or after its supplied next-day boundary, or after resuming without a reliable clock anchor, the client SHALL refresh context before choosing its date. If context cannot be obtained, the action SHALL remain retryable with visible date-unavailable feedback and SHALL NOT dispatch a guessed-date mutation.",
      "scenarios": []
    },
    {
      "name": "Preserve civil-date arithmetic through daylight saving changes",
      "text": "Calendar-day navigation and labels SHALL operate on civil dates. Advancing a date SHALL advance one date even when the elapsed interval is 23 or 25 hours. Calendar projections for different instants in a repeated hour SHALL identify the same date. Elapsed optimistic guard durations SHALL remain independent of timezone and wall-clock adjustments.",
      "scenarios": []
    }
  ],
  "metadata": {
    "version": "1.0.0",
    "format": "openspec"
  },
  "root": {
    "path": "/Users/alex/Code/whats-for-supper",
    "source": "nearest"
  }
}

actual_cli_stdout.household-identity:
{
  "id": "household-identity",
  "title": "household-identity",
  "overview": "Establish shared household access through passphrase entry and member invitations, apply household access-cookie and API authentication rules, and hand accepted access to separately owned member-context selection.",
  "requirementCount": 12,
  "requirements": [
    {
      "name": "Enter the household with its shared passphrase",
      "text": "With a configured household secret, Welcome SHALL compare the submitted passphrase and secret case-sensitively after trimming surrounding whitespace. On a match it SHALL obtain a signed household-access token, await writing its access cookie and request navigation to `/onboarding`. This entry SHALL establish shared access without creating a personal account or selecting a member.",
      "scenarios": []
    },
    {
      "name": "Give passphrase submission feedback and allow retry",
      "text": "Welcome SHALL disable Enter for whitespace-only input and during submission, and display checking feedback while submitting. A rejected passphrase result SHALL show an incorrect-passphrase message; an action or cookie-write exception SHALL show a generic retry message. After either failure it SHALL end checking, retain the input and allow resubmission of nonblank input. A new submission SHALL clear the previous error.",
      "scenarios": []
    },
    {
      "name": "Set household access-cookie options",
      "text": "The passphrase entry flow SHALL write its signed token as the HttpOnly `h_access` cookie with SameSite=Lax, path `/` and Max-Age of 31,536,000 seconds. It SHALL include the configured cookie domain when provided. It SHALL set Secure only in production when the public environment is not `test` and the configured domain does not contain `localhost`.",
      "scenarios": []
    },
    {
      "name": "Gate protected page entry with household access",
      "text": "For page requests subject to the PWA access gate, including `/onboarding`, the application SHALL require a configured secret and an access cookie accepted by its signature validation. Missing or rejected access SHALL redirect to `/welcome`. If a nonempty access cookie is present when access is rejected, the redirect response SHALL request its deletion.",
      "scenarios": []
    },
    {
      "name": "Authenticate protected API requests independently",
      "text": "API controller operations covered by household authorization SHALL authenticate shared access independently of the PWA page gate. An exact `X-Hearth-Secret` value or a signed HMAC Bearer token matching the configured secret SHALL satisfy household authentication. With no household credentials, or with only a rejected raw-secret header, they SHALL return 401. Endpoint-specific identity and eligibility checks SHALL remain separate.",
      "scenarios": []
    },
    {
      "name": "Exempt health from household authentication",
      "text": "GET `/api/health` SHALL permit requests without household credentials. This exemption SHALL concern authentication only and SHALL NOT guarantee the health of backing services.",
      "scenarios": []
    },
    {
      "name": "Generate a member invite link from Settings",
      "text": "Settings SHALL offer Invite for each displayed family member. Opening Invite SHALL show that member's name and request a link. Until a nonempty link is available, the dialog SHALL show generation feedback and disable its sharing controls. With a configured household secret and successful generation, it SHALL display a link at the current browser origin's `/invite` path with an encoded household-access token in `secret` and the target member ID in `memberId`.",
      "scenarios": []
    },
    {
      "name": "Copy share and dismiss the member invite dialog",
      "text": "With a generated link, the dialog SHALL offer Copy and offer Share when native sharing is available. Successful copying SHALL show temporary copied feedback. Share SHALL pass the generated link to native sharing. The dialog SHALL be dismissible through its Close control or surrounding overlay.",
      "scenarios": []
    },
    {
      "name": "Validate invite access before writing its access cookie",
      "text": "The invite page SHALL display joining feedback while processing. For a nonempty `secret` query value, it SHALL validate the household-access signature against the configured secret before writing that token to `h_access`. An accepted token and successful access-cookie write SHALL allow the invite to proceed to member-context handoff and navigation.",
      "scenarios": []
    },
    {
      "name": "Request the invited member context and default Home navigation",
      "text": "For an accepted invite supplying an existing member ID, after the access and initial member-cookie writes succeed, the application SHALL request selection of that member and mark onboarding complete. With no nonempty `redirect` parameter, it SHALL then request `/home`. Subsequent page gates, member resolution, recovery and selected-name display SHALL follow the existing household-identity requirements.",
      "scenarios": []
    },
    {
      "name": "Preserve member context when an invite supplies no member ID",
      "text": "After an accepted invite's access-cookie write succeeds, an absent or empty `memberId` SHALL leave existing member context and onboarding completion unchanged. With no nonempty `redirect`, the invite SHALL request `/home`, where the existing access and identity rules apply.",
      "scenarios": []
    },
    {
      "name": "Show invite rejection and offer Welcome recovery",
      "text": "A missing or empty token, rejected validation result or caught failure during validation or the initial access/member-cookie writes SHALL show the invalid-invite screen with a link to `/welcome`. Following that link SHALL open Welcome for the existing passphrase-entry journey.",
      "scenarios": []
    }
  ],
  "metadata": {
    "version": "1.0.0",
    "format": "openspec"
  },
